INSERT OR REPLACE INTO projects (id, sort_order, title, category, summary, image_url, stack_json, problem, implementation, constraints, outcome, result, result_note, links_json, sources_json) VALUES ('smc-crows', 1, 'SMC Crows v3.0', 'Android systems · Release engineering', 'Android 17 target compatibility, multi-tier dynamic hardware skinning, and non-destructive account preservation for thousands of mobile pilots.', 'assets/smc/SMC-audit-lobby.png', '["Android SDK 37", "Dynamic Skinning", "ARM64 Neon", "Cloudflare R2"]', 'Modern Android 17 runtime changes, 16 KB page-size enforcement, and aggressive GPU memory mapping in modern Qualcomm Adreno drivers caused fatal crashes and severe stutter on modern flagships.', 'Engineered the v3.0 release pipeline targeting Android 17 (SDK 37) with pageSizeCompat=''0x20'' and 16 KB ZIP page alignment. Developed a multi-tier dynamic skinning optimizer that routes 100% GPU hardware skinning for pilots (120 FPS) while using selective CPU Neon skinning for mechas to prevent GPU memory crashes. Built automated non-destructive account backup and a 15-part parallel Cloudflare R2 chunk distribution engine with MediaFire mirror fallback.', 'The vendor engine contains 29 legacy native libraries below 16 KB ELF boundary, requiring manifest compatibility mode. Tested across Samsung Galaxy S26 Ultra and Galaxy A54 devices.', 'Delivered smooth 120 FPS pilot movement and stable mecha combat on Android 17 hardware with zero driver freezes observed during testing. Successfully distributed via dual-route high-availability CDN while protecting player account progression.', '120 FPS · Android 17 target', 'Device-tested on Samsung S26 Ultra', '[{"label": "Explore SMC case study", "url": "smc/"}, {"label": "Download APK", "url": "smc/downloads/"}]', '[{"label": "SMC Release & Documentation", "url": "smc/"}, {"label": "APK SHA-256 Verification", "url": "smc/downloads/"}]');
INSERT OR REPLACE INTO projects (id, sort_order, title, category, summary, image_url, stack_json, problem, implementation, constraints, outcome, result, result_note, links_json, sources_json) VALUES ('checkout', 2, 'Hybrid Self-Checkout', 'Computer vision · Capstone', 'A second pair of eyes for the checkout counter. Barcode identity meets visual verification.', 'assets/thumb-yolov8.png', '["YOLOv8", "OpenCV", "Python", "MySQL"]', 'A barcode alone cannot tell whether the item in front of the camera is the item being scanned. Missed scans and item switching create gaps in conventional self-checkout.', 'Built a hybrid validation pipeline that identifies local retail products with YOLOv8 and compares detections with USB barcode scanner input. Python and OpenCV handle the video stream; MySQL stores product and transaction data. Split-view experiments address occlusion by observing products from multiple angles.', 'Similar packaging, overlapping items, lighting changes, and missed detections make visual verification difficult. Custom dataset of Malaysian retail items.', 'The project repository reports approximately 77.4% precision and 72.0% recall after 50 epochs.', '77.4% precision', 'Reported model benchmark · 50 epochs', '[{"label": "Explore source", "url": "https://github.com/l3al3y/FYP-PROJECT"}]', '[{"label": "Project README & architecture", "url": "https://github.com/l3al3y/FYP-PROJECT#readme"}]');
INSERT OR REPLACE INTO projects (id, sort_order, title, category, summary, image_url, stack_json, problem, implementation, constraints, outcome, result, result_note, links_json, sources_json) VALUES ('hermes', 3, 'Hermes', 'Agent systems · Edge infrastructure', 'Many models. One decision pipeline. An experiment in consensus, failure, and recovery on a phone.', 'assets/thumb-hermes.png', '["Python", "Termux", "LLM orchestration", "Cloudflare"]', 'An autonomous system needs more than a model response: it needs a way to weigh disagreement, handle unavailable providers, and inspect decisions after they fail.', 'Runs on a Samsung Galaxy A54 using Termux/Linux. A ''Parliament of Minds'' routes multiple LLM models through a consensus process. Separate serve and gateway processes, cron watchdog, telemetry, and causal post-mortems.', 'Mobile hardware and external model availability constrain reliability. Strategy refit pause recorded; operational status belongs to the telemetry console.', 'Documented multi-model orchestration experiment with observable operations and recovery mechanisms.', 'Consensus + recovery', 'Experimental system · contribution submitted', '[{"label": "Telemetry console", "url": "https://live.irfanfahmi.com"}, {"label": "View open PR #167", "url": "https://github.com/ashishpatel26/500-AI-Agents-Projects/pull/167"}]', '[{"label": "Contribution PR", "url": "https://github.com/ashishpatel26/500-AI-Agents-Projects/pull/167"}, {"label": "Telemetry", "url": "https://live.irfanfahmi.com"}]');
INSERT OR REPLACE INTO projects (id, sort_order, title, category, summary, image_url, stack_json, problem, implementation, constraints, outcome, result, result_note, links_json, sources_json) VALUES ('gesture', 4, 'Gesture recognition', 'Human interaction · Browser ML', 'Read without touching the screen. Hand geometry becomes a quiet, practical interface.', 'assets/thumb-irfanllm.png', '["MediaPipe Hands", "Random Forest", "JavaScript", "Python"]', 'Reading manga or webtoons while eating makes a touchscreen an awkward interface. A touchless controller needs deliberate gestures without scrolling again on the return stroke.', 'MediaPipe hand landmarks with 71-dimensional geometric features. A 100-tree Random Forest compiled to JavaScript for browser inference with a 0.30s scroll cooldown.', 'Camera permission, lighting, and browser support affect the experience.', 'Working browser controller with 98.6% cross-validation accuracy on training workflows.', '98.6% cross-validation', 'Reported score · not real-world accuracy', '[{"label": "Try the reader demo", "url": "manga.html"}, {"label": "Download extension", "url": "assets/manga/irfanllm-manga-extension.zip"}]', '[{"label": "Demo notes", "url": "manga.html"}, {"label": "Controller source", "url": "https://github.com/l3al3y/Portfolio/blob/main/controller.js"}]');
INSERT OR REPLACE INTO projects (id, sort_order, title, category, summary, image_url, stack_json, problem, implementation, constraints, outcome, result, result_note, links_json, sources_json) VALUES ('livestock', 5, 'IoT livestock monitoring', 'Embedded systems · Team project', 'From a physical load to a useful reading. A connected weighing platform built around the sensor.', '', '["Arduino", "HX711", "Load cells", "C/C++"]', 'Tracking livestock weight requires a repeatable way to turn physical measurements into readings that can be monitored over time.', 'Load-cell weighing platform using Arduino microcontrollers, HX711 amplifiers, and C/C++ signal filtering firmware.', 'Calibration and signal stability matter as much as connectivity.', 'Team received Third Place at INOTEK 2025 (Series 1) on 15 January 2025.', 'INOTEK 2025 · Third Place', 'Documented team award · 15 January 2025', '[{"label": "View award document", "url": "certificates/INOTEK_2025_Third_Place.pdf"}]', '[{"label": "INOTEK award certificate", "url": "certificates/INOTEK_2025_Third_Place.pdf"}]');
INSERT OR REPLACE INTO projects (id, sort_order, title, category, summary, image_url, stack_json, problem, implementation, constraints, outcome, result, result_note, links_json, sources_json) VALUES ('arcade', 6, 'Mini Arcade', 'Interactive software · Web', 'A small playground for decisions, timing, and memory. Short sessions, built for the browser.', 'assets/thumb-arcade.png', '["React", "TypeScript", "Game logic", "Tailwind CSS"]', 'A browser game needs clear feedback, responsive controls, and enough structure to make a short session feel complete.', 'Minimax-based Tic Tac Toe, penalty shootout, and sports memory match with link-based online multiplayer.', 'Cross-device touch and desktop support.', 'Four games available live exploring decision trees and interface state.', 'Three core games + a beta', 'Live application on arcade.irfanfahmi.com', '[{"label": "Launch Mini Arcade", "url": "https://arcade.irfanfahmi.com"}]', '[{"label": "Live application", "url": "https://arcade.irfanfahmi.com"}]');